import{d as g,C as i,o as h,c as u,a3 as a,E as e,j as t,a as d}from"./chunks/framework.Q4yG9rk_.js";const b=JSON.parse('{"title":"论语·尧曰","description":"《论语》第 20 篇「尧曰」——三章原文与导读。允执其中、四海困穷天禄永终、尊五美屏四恶，以及全书末章「不知命，无以为君子也」。","frontmatter":{"title":"论语·尧曰","description":"《论语》第 20 篇「尧曰」——三章原文与导读。允执其中、四海困穷天禄永终、尊五美屏四恶，以及全书末章「不知命，无以为君子也」。","category":"guide","aliases":["尧曰","尧曰篇","尧曰第二十","论语尧曰","lunyu 尧曰"],"source":["《论语》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/lunyu/chapter-20.md","filePath":"lizhimingde/sishu-wujing/lunyu/chapter-20.md","lastUpdated":1790316338000}'),p={name:"lizhimingde/sishu-wujing/lunyu/chapter-20.md"},x=g({...p,setup(m){const o=[{id:"yi",label:"一、允执其中",showLabel:!0,sentences:[["尧曰：“咨！尔舜，天之",{text:"历数",glossary:"lishu"},"在尔躬，",{text:"允执其中",glossary:"yunzhihaiqizhong"},"。四海困穷，天禄永终。”舜亦以命禹。曰：“予小子",{text:"履",glossary:"lv-shang"},"，敢用",{text:"玄牡",glossary:"xuanmu"},"，敢昭告于皇皇后帝：有罪不敢赦，帝臣不",{text:"蔽",glossary:"bi-bai"},"，",{text:"简在帝心",glossary:"jianzaidixin"},"。朕躬有罪，无以万方；万方有罪，罪在朕躬。”周有大",{text:"赉",glossary:"lai"},"，善人是富。“虽有周亲，不如仁人。百姓有过，在予一人。”谨权量，审法度，修废官，四方之政行焉。兴灭国，继绝世，举逸民，天下之民归心焉。所重：民、食、丧、祭。宽则得众，信则民任焉，敏则有功，公则说。"]],note:"尧曰：「咨！尔舜，天之历数在尔躬，允执其中。四海困穷，天禄永终」——唉！舜啊，上天之大命在尔身，当诚实地执守中道；若四海之民困穷，天禄便永终。舜亦以此命禹，曰：「予小子履，敢用玄牡，敢昭告于皇皇后帝：有罪不敢赦，帝臣不蔽，简在帝心。朕躬有罪，无以万方；万方有罪，罪在朕躬」——舜又以此告诫禹，说：我后生小子履，敢用黑色公牛，明告于伟大的天帝：有罪者不敢赦，天帝之臣不敢蔽，皆由天帝心中鉴察；朕身有罪，不连累万方；万方有罪，罪在朕身。（其后又记周之大赉、虽有周亲不如仁人、谨权量审法度、兴灭国继绝世等诰命之辞，合为一章。）"},{id:"er",label:"二、尊五美，屏四恶",showLabel:!0,sentences:[["子张问于孔子曰：“何如斯可以从政矣？”子曰：“尊五美，屏四恶，斯可以从政矣。”子张曰：“何谓五美？”子曰：“君子惠而不费，劳而不怨，欲而不贪，泰而不骄，威而不猛。”子张曰：“何谓惠而不费？”子曰：“因民之所利而利之，斯不亦惠而不费乎？择可劳而劳之，又谁怨？欲仁而得仁，又焉贪？君子无众寡，无小大，无敢慢，斯不亦泰而不骄乎？君子正其衣冠，尊其瞻视，俨然人望而畏之，斯不亦威而不猛乎？”子张曰：“何谓四恶？”子曰：“不教而杀谓之虐；不戒视成谓之暴；慢令致期谓之贼；犹之与人也，出纳之",{text:"吝",glossary:"lin-yao"},"，谓之",{text:"有司",glossary:"yousi"},"。”"]],note:"子张问于孔子曰：「何如斯可以从政矣」？子曰：「尊五美，屏四恶，斯可以从政矣」——尊五美、屏四恶，斯可从政。曰「何谓五美」？曰：「君子惠而不费，劳而不怨，欲而不贪，泰而不骄，威而不猛」。曰「何谓惠而不费」？曰：「因民之所利而利之，斯不亦惠而不费乎？择可劳而劳之，又谁怨？欲仁而得仁，又焉贪？君子无众寡，无小大，无敢慢，斯不亦泰而不骄乎？君子正其衣冠，尊其瞻视，俨然人望而畏之，斯不亦威而不猛乎」——就民所利而利之，即惠而不费；择可劳而劳之，又何怨？欲仁得仁，又何贪？无众寡小大皆不慢，即泰而不骄；正衣冠、尊瞻视、俨然可畏，即威而不猛。曰「何谓四恶」？曰：「不教而杀谓之虐，不戒视成谓之暴，慢令致期谓之贼，犹之与人也，出纳之吝谓之有司」——不教而杀谓之虐，不戒而责成谓之暴，慢令而致期谓之贼，当予而吝于出纳谓之有司（小家子气）。"},{id:"san",label:"三、不知命，无以为君子也",showLabel:!0,sentences:[["孔子曰：“不知命，无以为君子也；不知礼，无以立也；不知言，无以知人也。”"]],note:"孔子曰：「不知命，无以为君子也；不知礼，无以立也；不知言，无以知人也」——不知命则无以为君子，不知礼则无以立身，不知言则无以知人。三句收束全书。"}],r=[{id:"lishu",term:"历数",pinyin:"lì shù",meaning:"天道运行的次序，此指天命所归的运数。"},{id:"yunzhihaiqizhong",term:"允执其中",pinyin:"yǔn zhí qí zhōng",meaning:"诚实地持守中正之道。这句是儒家「执中」之说的源头，后来成为「十六字心传」的核心。"},{id:"lv-shang",term:"履",pinyin:"lǚ",meaning:"商汤的名。此下为汤告天之辞。"},{id:"xuanmu",term:"玄牡",pinyin:"xuán mǔ",meaning:"黑色的公牛（祭祀用牲）。"},{id:"bi-bai",term:"蔽",pinyin:"bì",meaning:"遮蔽、隐瞒。帝臣不蔽：对天帝的臣属（贤人）不敢隐瞒不举。"},{id:"jianzaidixin",term:"简在帝心",pinyin:"jiǎn zài dì xīn",meaning:"简：阅、明察（一说「简」为「存」）。天帝心里明白——即一切都在天帝鉴察之中。"},{id:"lai",term:"赉",pinyin:"lài",meaning:"赏赐。周有大赉：周朝得到上天的丰厚赏赐（指得天下）。"},{id:"lin-yao",term:"吝",pinyin:"lìn",meaning:"吝啬、舍不得。出纳之吝：该给的时候舍不得给。"},{id:"yousi",term:"有司",pinyin:"yǒu sī",meaning:"专管具体事务的官吏。此处指「像管库房的小吏那样小家子气」，是贬义比喻。"}];return(y,n)=>{const s=i("DaoTextReading"),l=i("DaoKeywordCards");return h(),u("div",null,[n[0]||(n[0]=a("",7)),e(s,{colophon:"尧曰第二十 · 三章",tone:"ink",sections:o,glossary:r,"default-mode":"slips","aria-label":"论语·尧曰 原文"}),n[1]||(n[1]=t("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[d("【原典层】注音与字词 "),t("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),e(l,{items:[{term:"历数",pinyin:["lì","shù"],meaning:"天道运行的次序，此指天命所归的运数。"},{term:"允执其中",pinyin:["yǔn","zhí","qí","zhōng"],meaning:"诚实地持守中正之道。这句是儒家「执中」之说的源头，后来成为「十六字心传」的核心。"},{term:"履",pinyin:["lǚ"],meaning:"商汤的名。此下为汤告天之辞。"},{term:"玄牡",pinyin:["xuán","mǔ"],meaning:"黑色的公牛（祭祀用牲）。"},{term:"蔽",pinyin:["bì"],meaning:"遮蔽、隐瞒。帝臣不蔽：对天帝的臣属（贤人）不敢隐瞒不举。"},{term:"简在帝心",pinyin:["jiǎn","zài","dì","xīn"],meaning:"简：阅、明察（一说「简」为「存」）。天帝心里明白——即一切都在天帝鉴察之中。"},{term:"赉",pinyin:["lài"],meaning:"赏赐。周有大赉：周朝得到上天的丰厚赏赐（指得天下）。"},{term:"吝",pinyin:["lìn"],meaning:"吝啬、舍不得。出纳之吝：该给的时候舍不得给。"},{term:"有司",pinyin:["yǒu","sī"],meaning:"专管具体事务的官吏。此处指「像管库房的小吏那样小家子气」，是贬义比喻。"}]}),n[2]||(n[2]=a("",26))])}}});export{b as __pageData,x as default};
